-- PostgreSQL: run manually if using tables-enterprise on Postgres (not generated by drizzle-kit MySQL flow).

CREATE TABLE IF NOT EXISTS managed_llm_models (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id UUID NOT NULL REFERENCES organizations (id) ON DELETE CASCADE,
  name VARCHAR(255) NOT NULL,
  provider VARCHAR(64) NOT NULL,
  model_key VARCHAR(512) NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'active',
  health_status VARCHAR(20) NOT NULL DEFAULT 'unknown',
  quota_monthly INTEGER NOT NULL DEFAULT 100000,
  quota_used INTEGER NOT NULL DEFAULT 0,
  provider_config JSONB,
  metadata JSONB,
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS managed_llm_models_organization_id_idx ON managed_llm_models (organization_id);
